const body = $input.first().json.body ?? $input.first().json;
const vehicleModel = (body.vehicle_model ?? '').trim();
const vehicleVersion = (body.vehicle_version ?? '').trim();
const customerVehicleId = body.customer_vehicle_id;
const clientId = body.client_id;

if (!vehicleModel) {
  return [{ json: { valid: false, error: 'vehicle_model es requerido' } }];
}
if (!customerVehicleId) {
  return [{ json: { valid: false, error: 'customer_vehicle_id es requerido' } }];
}

return [{ json: { valid: true, client_id: clientId, customer_vehicle_id: customerVehicleId, vehicle_model: vehicleModel, vehicle_version: vehicleVersion } }];

const raw = $input.first().json.output ?? '';
const ctx = $('Validate Input').first().json;

// Strip markdown code blocks if the LLM wrapped the JSON
const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{ json: {
    client_id: ctx.client_id,
    customer_vehicle_id: ctx.customer_vehicle_id,
    vehicle_model: ctx.vehicle_model,
    vehicle_version: ctx.vehicle_version,
    parse_error: true,
    not_found: true
  }}];
}

return [{ json: {
  client_id: ctx.client_id,
  customer_vehicle_id: ctx.customer_vehicle_id,
  vehicle_model: ctx.vehicle_model,
  vehicle_version: ctx.vehicle_version,
  ...parsed
}}];

